# Kaggriculture agent: replays a fixed 719-step schedule inside a reactive chassis. Apache-2.0. Credits: thomastschinkel, yhay81, tetsutani (chassis/tapes).
from __future__ import annotations
import copy
PRODUCTS = ('WHEAT', 'CARROT', 'TOMATO', 'STRAWBERRY', 'MELON', 'EGG', 'MILK', 'WOOL', 'FERTILIZER')
SEED_PRICE = {'WHEAT': 10, 'CARROT': 20, 'TOMATO': 50, 'STRAWBERRY': 100, 'MELON': 80}
ANIMAL_COST = {'GOOSE': 300, 'COW': 400, 'SHEEP': 500}
ANIMAL_STRUCTURE = {'GOOSE': 'COOP', 'COW': 'PASTURE', 'SHEEP': 'PASTURE'}
LAND_PRICES = (1000, 2000, 4000)
MOVES = {'NORTH': (0, -1), 'SOUTH': (0, 1), 'EAST': (1, 0), 'WEST': (-1, 0)}
FRONT_RUN_ITEMS = ('MILK', 'WOOL', 'STRAWBERRY', 'MELON')
LAST_ACT_STEP = 718
PASS_ACTION = {'farmer': ['PASS'], 'hands': [], 'market': []}
DEFAULT_SETTINGS = {'hand_align': True, 'weed_repair': True, 'sell_lead': True, 'front_run': True, 'budget_guard': True, 'room_guard': True, 'clamp_sells': True, 'dead_stock': True, 'terminal_liquidation': True, 'block_turns': 72, 'shed_capacity': 100, 'board_size': 10, 'max_orders': 10, 'turns_per_day': 24, 'min_sell_price': 2}

def _get(value, key, default=None):
    if isinstance(value, dict):
        return value.get(key, default)
    getter = getattr(value, 'get', None)
    if callable(getter):
        return getter(key, default)
    return getattr(value, key, default)

def _int(value, default=0):
    try:
        return int(value)
    except (TypeError, ValueError):
        return default

def _fib(n):
    a, b = (1, 1)
    for _ in range(n):
        a, b = (b, a + b)
    return a

def _step_of(observation):
    raw = _get(observation, 'step')
    if raw is not None:
        return _int(raw)
    return _int(_get(observation, 'day', 0)) * 24 + _int(_get(observation, 'hour', 0))

def _shed_adjacent(pos, board):
    if not isinstance(pos, (list, tuple)) or len(pos) < 2:
        return False
    half = board // 2
    return pos[0] in (half - 1, half) and pos[1] in (half - 1, half)

def _tile_at(tiles, pos):
    try:
        x, y = (int(pos[0]), int(pos[1]))
        return tiles[y][x]
    except (TypeError, ValueError, IndexError):
        return 'LOCKED'

def _is_noop(act, tile, inv, seeds, pos, board):
    if not act:
        return True
    op = act[0]
    x, y = (pos[0], pos[1])
    if op in MOVES:
        dx, dy = MOVES[op]
        return not (0 <= x + dx < board and 0 <= y + dy < board)
    if op == 'PASS':
        return True
    adjacent = _shed_adjacent(pos, board)
    if op == 'DROP':
        return not adjacent or not inv
    if op == 'PICKUP':
        return not adjacent
    if op == 'PLACE':
        item = act[1] if len(act) > 1 else None
        if item in ANIMAL_STRUCTURE and isinstance(tile, dict) and (_get(tile, 'kind') == ANIMAL_STRUCTURE[item]) and (_get(tile, 'animal') is None):
            return _int(_get(inv, item, 0)) <= 0
        return not adjacent or _int(_get(inv, item, 0)) <= 0
    if tile == 'LOCKED':
        return True
    is_dict = isinstance(tile, dict)
    kind = _get(tile, 'kind') if is_dict else None
    animal = is_dict and _get(tile, 'animal') is not None
    if op == 'PLANT':
        return tile is not None or _int(_get(seeds, act[1] if len(act) > 1 else None, 0)) <= 0
    if op == 'WATER':
        return kind != 'PLANT' or bool(_get(tile, 'watered_today'))
    if op == 'HARVEST':
        return not is_dict or _int(_get(tile, 'yield_units', 0)) <= 0
    if op == 'FERTILIZE':
        return kind != 'PLANT' or _int(_get(inv, 'FERTILIZER', 0)) <= 0
    if op == 'DIG':
        return tile is None or animal
    if op in ('BUILD_COOP', 'BUILD_PASTURE'):
        return tile is not None
    if op == 'FEED':
        return not animal or bool(_get(tile, 'fed_today')) or _int(_get(inv, 'WHEAT', 0)) <= 0
    if op == 'COLLECT_FERTILIZER':
        return not animal or not _get(tile, 'fertilizer_available')
    if op == 'CARE':
        return not animal or bool(_get(tile, 'cared_today'))
    return True

class _View:

    def __init__(self, observation, player, cfg):
        farms = list(_get(observation, 'farms', []) or [])
        self.farm = farms[player] if player < len(farms) else {}
        self.rival = farms[1 - player] if len(farms) >= 2 and 1 - player < len(farms) else {}
        private = _get(observation, 'private', {}) or {}
        self.shed = {k: max(0, _int(v)) for k, v in dict(_get(private, 'shed', {}) or {}).items()}
        self.seeds = dict(_get(private, 'seeds', {}) or {})
        self.invs = [dict(i or {}) for i in _get(private, 'inventories', []) or []]
        market = _get(observation, 'market', {}) or {}
        self.prices = {k: _int(v) for k, v in dict(_get(market, 'prices', {}) or {}).items()}
        self.money = float(_get(self.farm, 'money', 0.0) or 0.0)
        self.tiles = _get(self.farm, 'tiles', []) or []
        self.board = len(self.tiles) or cfg['board_size']
        self.positions = [_get(self.farm, 'farmer', None)] + [list(p) for p in _get(self.farm, 'hands', []) or []]
        self.hires_today = _int(_get(self.farm, 'hires_today', 0))
        self.quadrants = len(list(_get(self.farm, 'unlocked_quadrants', []) or []))

    def inv(self, idx):
        return self.invs[idx] if idx < len(self.invs) else {}

    def in_hands(self, item):
        return sum((max(0, _int(_get(inv, item, 0))) for inv in self.invs))

class Chassis:

    def __init__(self, routes, router=None, settings=None, opponent_plan=None):
        self.routes = {rid: list(tape) for rid, tape in routes.items()}
        self.router = router or (lambda observation, step, state: next(iter(self.routes)))
        self.cfg = dict(DEFAULT_SETTINGS)
        self.cfg.update(settings or {})
        self.opponent_plan = opponent_plan
        self.players = {}
        self.diagnostics = {'layer_fallbacks': 0, 'entry_fallbacks': 0}
        self._future_sells = {}

    def _state(self, player, step):
        st = self.players.get(player)
        if st is None or step == 0 or step <= st['last_step']:
            st = {'last_step': -1, 'route': None, 'router_state': {}, 'pending': {}, 'sell_state': {'due_step': -1, 'suppress': {}}}
            self.players[player] = st
        st['last_step'] = step
        return st

    def _route_action(self, route, step):
        tape = self.routes[route]
        if 0 <= step < len(tape) and isinstance(tape[step], dict):
            return copy.deepcopy(tape[step])
        return copy.deepcopy(PASS_ACTION)

    def future_sells(self, route, item, step):
        table = self._future_sells.get(route)
        if table is None:
            tape = self.routes[route]
            n = len(tape)
            table = {p: [0] * (n + 1) for p in PRODUCTS}
            for t in range(n - 1, -1, -1):
                for p in PRODUCTS:
                    table[p][t] = table[p][t + 1]
                for o in tape[t].get('market') or [] if isinstance(tape[t], dict) else []:
                    if o and o[0] == 'SELL' and (len(o) >= 3) and (o[1] in table):
                        table[o[1]][t] += max(0, _int(o[2]))
            self._future_sells[route] = table
        col = table.get(item)
        return col[step] if col and 0 <= step < len(col) else 0

    def act(self, observation, configuration=None):
        if len(_get(observation, 'farms', []) or []) < 2:
            raise ValueError('incomplete observation')
        step = _step_of(observation)
        player = _int(_get(observation, 'player', 0))
        st = self._state(player, step)
        cfg = self.cfg
        view = _View(observation, player, cfg)
        route = self.router(observation, step, st['router_state'])
        if route not in self.routes:
            route = st['route'] if st['route'] in self.routes else next(iter(self.routes))
        st['route'] = route
        action = self._route_action(route, step)
        raw = copy.deepcopy(action)
        try:
            if cfg['hand_align']:
                self._hand_align(action, view)
            if cfg['weed_repair']:
                self._weed_repair(action, view, st, route, step)
            if cfg['sell_lead'] or cfg['front_run']:
                self._apply_suppression(action, st['sell_state'], step)
            projected = self._projected_shed(action, view)
            lead_available = dict(projected)
            next_sup = {'due_step': -1, 'suppress': {}}
            if cfg['sell_lead']:
                self._sell_lead(action, view, lead_available, route, step, next_sup)
            if cfg['front_run'] and self.opponent_plan:
                self._front_run(action, view, lead_available, route, step, next_sup)
            st['sell_state'] = next_sup
            if cfg['budget_guard']:
                self._budget_guard(action, view, route, step)
            if cfg['room_guard']:
                self._room_guard(action, view, route, step)
            if cfg['clamp_sells']:
                self._clamp_sells(action, projected)
            if cfg['dead_stock']:
                self._dead_stock(action, view, projected, route, step)
            if cfg['terminal_liquidation']:
                self._terminal_liquidation(action, projected, step)
            action['market'] = action['market'][:cfg['max_orders']]
            return action
        except Exception:
            self.diagnostics['layer_fallbacks'] += 1
            return raw

    def _hand_align(self, action, view):
        expected = max(0, len(view.positions) - 1)
        hands = list(action.get('hands') or [])
        hands.extend([['PASS'] for _ in range(max(0, expected - len(hands)))])
        action['hands'] = hands[:expected]

    def _weed_repair(self, action, view, st, route, step):
        units = [action.get('farmer') or ['PASS']] + list(action.get('hands') or [])
        pending = st['pending']
        tape = self.routes[route]
        nxt = tape[step + 1] if step + 1 < len(tape) and isinstance(tape[step + 1], dict) else {}
        next_units = [nxt.get('farmer') or ['PASS']] + list(nxt.get('hands') or [])
        for i in range(min(len(units), len(view.positions))):
            pos = view.positions[i]
            if not isinstance(pos, (list, tuple)):
                continue
            pos = (int(pos[0]), int(pos[1]))
            tile = _tile_at(view.tiles, pos)
            act = list(units[i])
            queue = pending.get(i)
            if queue and queue[0][0] != pos:
                pending.pop(i, None)
                queue = None
            is_weed = isinstance(tile, dict) and _get(tile, 'kind') == 'WEED'
            noop = _is_noop(act, tile, view.inv(i), view.seeds, pos, view.board)
            next_op = next_units[i][0] if i < len(next_units) and next_units[i] else 'PASS'
            if act and act[0] in ('PLANT', 'BUILD_COOP', 'BUILD_PASTURE') and is_weed:
                pending.setdefault(i, []).append((pos, act))
                act = ['DIG']
            elif queue and noop:
                _, replay = queue[0]
                if replay[0] == 'PLANT' and next_op in MOVES:
                    pending.pop(i, None)
                else:
                    queue.pop(0)
                    if act and act[0] != 'PASS' and (act[0] not in MOVES):
                        queue.append((pos, act))
                    act = replay
                    if not queue:
                        pending.pop(i, None)
            elif is_weed and noop:
                act = ['DIG']
            units[i] = act
        action['farmer'] = units[0]
        action['hands'] = units[1:]

    def _projected_shed(self, action, view):
        cap = self.cfg['shed_capacity']
        proj = {p: view.shed.get(p, 0) for p in PRODUCTS}
        for k, v in view.shed.items():
            proj.setdefault(k, v)
        total = sum(proj.values())
        units = [action.get('farmer') or ['PASS']] + list(action.get('hands') or [])
        for i in range(min(len(units), len(view.positions))):
            if not _shed_adjacent(view.positions[i], view.board):
                continue
            act = units[i]
            op = act[0] if act else 'PASS'
            inv = view.inv(i)
            if op == 'PICKUP' and len(act) >= 2 and (act[1] in proj):
                qty = min(proj[act[1]], max(0, _int(act[2]) if len(act) >= 3 else 1))
                proj[act[1]] -= qty
                total -= qty
            elif op == 'DROP':
                for item, held in inv.items():
                    take = min(max(0, _int(held)), max(0, cap - total))
                    if take > 0:
                        proj[item] = proj.get(item, 0) + take
                        total += take
            elif op == 'PLACE' and len(act) >= 2 and (act[1] not in ANIMAL_STRUCTURE):
                item = act[1]
                take = min(max(0, _int(act[2]) if len(act) >= 3 else 1), max(0, _int(_get(inv, item, 0))), max(0, cap - total))
                if take > 0:
                    proj[item] = proj.get(item, 0) + take
                    total += take
        return proj

    @staticmethod
    def _apply_suppression(action, sell_state, step):
        if sell_state.get('due_step') != step:
            return
        remaining = dict(sell_state.get('suppress', {}))
        kept = []
        for order in action.get('market') or []:
            order = list(order)
            if order and order[0] == 'SELL' and (len(order) >= 3) and (remaining.get(order[1], 0) > 0):
                removed = min(max(0, _int(order[2])), remaining[order[1]])
                order[2] = _int(order[2]) - removed
                remaining[order[1]] -= removed
            kept.append(order)
        action['market'] = kept

    @staticmethod
    def _add_sell(action, item, qty, max_orders, merge=True):
        market = action.setdefault('market', [])
        if merge:
            for order in market:
                if order and order[0] == 'SELL' and (order[1] == item):
                    order[2] = _int(order[2]) + qty
                    return True
        if len(market) >= max_orders:
            return False
        market.append(['SELL', item, qty])
        return True

    def _sell_lead(self, action, view, projected, route, step, next_sup):
        cfg = self.cfg
        nxt = step + 1
        unlock_period = 3 * cfg['turns_per_day']
        if nxt > LAST_ACT_STEP or nxt % unlock_period == 0 or step % 4 == 0:
            return
        tape = self.routes[route]
        future = tape[nxt] if nxt < len(tape) and isinstance(tape[nxt], dict) else {}
        planned = {}
        for o in future.get('market') or []:
            if o and o[0] == 'SELL' and (len(o) >= 3) and (o[1] in PRODUCTS):
                planned[o[1]] = planned.get(o[1], 0) + max(0, _int(o[2]))
        already = {o[1] for o in action.get('market') or [] if o and o[0] == 'SELL' and (len(o) > 1)}
        for item in PRODUCTS:
            if item in ('WHEAT', 'FERTILIZER') or planned.get(item, 0) <= 0 or item in already:
                continue
            qty = min(projected.get(item, 0), planned[item])
            if qty <= 0 or view.prices.get(item, 0) < cfg['min_sell_price']:
                continue
            if not self._add_sell(action, item, qty, cfg['max_orders'], merge=False):
                break
            projected[item] -= qty
            next_sup['suppress'][item] = next_sup['suppress'].get(item, 0) + qty
        if next_sup['suppress']:
            next_sup['due_step'] = nxt

    def _front_run(self, action, view, projected, route, step, next_sup):
        cfg = self.cfg
        nxt = step + 1
        plan = self.opponent_plan
        if nxt > LAST_ACT_STEP or nxt >= len(plan) or (not isinstance(plan[nxt], dict)):
            return
        already = {o[1] for o in action.get('market') or [] if o and o[0] == 'SELL' and (len(o) > 1)}
        for o in plan[nxt].get('market') or []:
            if not (o and o[0] == 'SELL' and (len(o) >= 3) and (o[1] in FRONT_RUN_ITEMS)):
                continue
            item = o[1]
            if item in already or view.prices.get(item, 0) < cfg['min_sell_price']:
                continue
            own_next = sum((max(0, _int(x[2])) for x in self.routes[route][nxt].get('market', []) if len(x) >= 3 and x[0] == 'SELL' and (x[1] == item)))
            qty = min(projected.get(item, 0), max(0, _int(o[2])), own_next)
            if qty <= 0:
                continue
            if not self._add_sell(action, item, qty, cfg['max_orders'], merge=False):
                break
            projected[item] -= qty
            already.add(item)
            next_sup['suppress'][item] = next_sup['suppress'].get(item, 0) + qty
        if next_sup['suppress']:
            next_sup['due_step'] = nxt

    def _block_requirements(self, view, route, start, end):
        tape = self.routes[route]
        budget = 0.0
        seed_bal, item_bal = ({}, {})
        seed_need, item_need = ({}, {})
        hires_by_day = {}
        quadrants = view.quadrants
        for t in range(start, min(end, len(tape))):
            a = tape[t] if isinstance(tape[t], dict) else {}
            for u in [a.get('farmer') or ['PASS']] + list(a.get('hands') or []):
                if not u:
                    continue
                op = u[0]
                arg = u[1] if len(u) > 1 else None
                qty = max(1, _int(u[2]) if len(u) > 2 else 1)
                if op == 'PLANT' and arg in SEED_PRICE:
                    seed_bal[arg] = seed_bal.get(arg, 0) - 1
                    seed_need[arg] = max(seed_need.get(arg, 0), -seed_bal[arg])
                elif op == 'FEED':
                    item_bal['WHEAT'] = item_bal.get('WHEAT', 0) - 1
                    item_need['WHEAT'] = max(item_need.get('WHEAT', 0), -item_bal['WHEAT'])
                elif op == 'FERTILIZE':
                    item_bal['FERTILIZER'] = item_bal.get('FERTILIZER', 0) - 1
                    item_need['FERTILIZER'] = max(item_need.get('FERTILIZER', 0), -item_bal['FERTILIZER'])
                elif op == 'PLACE' and arg is not None:
                    item_bal[arg] = item_bal.get(arg, 0) - qty
                    item_need[arg] = max(item_need.get(arg, 0), -item_bal[arg])
            for o in a.get('market') or []:
                if not o:
                    continue
                op = o[0]
                item = o[1] if len(o) > 1 else None
                qty = max(1, _int(o[2]) if len(o) > 2 else 1)
                if op == 'HIRE':
                    day = (t - start) // self.cfg['turns_per_day']
                    hires_by_day[day] = hires_by_day.get(day, 0) + 1
                elif op == 'BUY_LAND':
                    extra = quadrants - 1
                    if 0 <= extra < len(LAND_PRICES):
                        budget += LAND_PRICES[extra]
                        quadrants += 1
                elif op == 'BUY_SEED' and item in SEED_PRICE:
                    budget += SEED_PRICE[item] * qty
                    seed_bal[item] = seed_bal.get(item, 0) + qty
                elif op == 'BUY_PRODUCT' and item in ('WHEAT', 'FERTILIZER'):
                    budget += view.prices.get(item, 0) * qty
                    item_bal[item] = item_bal.get(item, 0) + qty
                elif op == 'BUY_ANIMAL' and item in ANIMAL_COST:
                    budget += ANIMAL_COST[item] * qty
                    item_bal[item] = item_bal.get(item, 0) + qty
        for day, n in hires_by_day.items():
            first = view.hires_today if day == 0 else 0
            for k in range(n):
                budget += _fib(first + k)
        return (budget, item_need)

    def _budget_guard(self, action, view, route, step):
        cfg = self.cfg
        block = cfg['block_turns']
        if block <= 0 or step % block != 0:
            return
        budget, item_need = self._block_requirements(view, route, step, step + block)
        market = action.setdefault('market', [])
        existing = {}
        for o in market:
            if o and o[0] == 'SELL' and (len(o) >= 3):
                existing[o[1]] = existing.get(o[1], 0) + max(0, _int(o[2]))
        cash = view.money
        for item in PRODUCTS:
            planned = max(existing.get(item, 0), self.future_sells(route, item, step) - self.future_sells(route, item, step + block))
            cash += min(view.shed.get(item, 0), planned) * view.prices.get(item, 0)
        shortfall = budget - cash
        if shortfall <= 0:
            return
        candidates = []
        for item in PRODUCTS:
            price = view.prices.get(item, 0)
            if price < cfg['min_sell_price']:
                continue
            protected = max(0, item_need.get(item, 0) - view.in_hands(item))
            avail = view.shed.get(item, 0) - protected - existing.get(item, 0)
            if avail > 0:
                candidates.append((-price, item, avail, price))
        candidates.sort()
        added = False
        for _, item, avail, price in candidates:
            if shortfall <= 0:
                break
            qty = min(avail, -(-int(shortfall) // price))
            if self._add_sell(action, item, qty, cfg['max_orders']):
                shortfall -= qty * price
                added = True
        if added:
            sells = [o for o in market if o and o[0] == 'SELL']
            others = [o for o in market if not (o and o[0] == 'SELL')]
            action['market'] = sells + others

    def _room_guard(self, action, view, route, step):
        cfg = self.cfg
        if step % cfg['turns_per_day'] != cfg['turns_per_day'] - 1:
            return
        cap = cfg['shed_capacity']
        units = [action.get('farmer') or ['PASS']] + list(action.get('hands') or [])
        carried = sum((max(0, _int(n)) for inv in view.invs for n in inv.values()))
        produced = consumed = 0
        for i in range(min(len(units), len(view.positions))):
            tile = _tile_at(view.tiles, view.positions[i])
            a = units[i]
            if not a:
                continue
            op = a[0]
            if op == 'HARVEST' and isinstance(tile, dict):
                produced += max(0, _int(_get(tile, 'yield_units', 0)))
            elif op == 'COLLECT_FERTILIZER' and isinstance(tile, dict) and _get(tile, 'fertilizer_available'):
                produced += 1
            elif op in ('FEED', 'FERTILIZE'):
                consumed += 1
            elif op == 'PLACE' and len(a) > 1 and (a[1] in ANIMAL_STRUCTURE):
                consumed += 1
        market = action.setdefault('market', [])
        planned_sells, planned_buys = ({}, 0)
        for o in market:
            if not o:
                continue
            if o[0] == 'SELL' and len(o) >= 3:
                planned_sells[o[1]] = planned_sells.get(o[1], 0) + max(0, _int(o[2]))
            elif o[0] in ('BUY_PRODUCT', 'BUY_ANIMAL') and len(o) >= 3:
                planned_buys += max(0, _int(o[2]))
        shed_total = sum(view.shed.values())
        fillable = sum((min(view.shed.get(it, 0), n) for it, n in planned_sells.items()))
        needed = shed_total + carried + produced - consumed + planned_buys - fillable - (cap - 1)
        if needed <= 0:
            return
        priority = sorted(PRODUCTS, key=lambda it: (self.future_sells(route, it, step + 1) > 0, -view.prices.get(it, 0), it))
        for item in priority:
            avail = max(0, view.shed.get(item, 0) - planned_sells.get(item, 0))
            qty = min(needed, avail)
            if qty <= 0 or view.prices.get(item, 0) < 1:
                continue
            if not self._add_sell(action, item, qty, cfg['max_orders']):
                continue
            planned_sells[item] = planned_sells.get(item, 0) + qty
            needed -= qty
            if needed <= 0:
                break

    @staticmethod
    def _clamp_sells(action, projected):
        avail = dict(projected)
        kept = []
        for o in action.get('market') or []:
            if o and o[0] == 'SELL' and (len(o) >= 3):
                have = avail.get(o[1], 0)
                n = min(_int(o[2]), have)
                n = max(0, n)
                avail[o[1]] = have - n
                kept.append(['SELL', o[1], n])
            else:
                kept.append(o)
                if o and o[0] in ('BUY_PRODUCT', 'BUY_ANIMAL') and (len(o) >= 3):
                    avail[o[1]] = avail.get(o[1], 0) + max(0, _int(o[2]))
        action['market'] = kept

    def _dead_stock(self, action, view, projected, route, step):
        planned = {}
        for o in action.get('market') or []:
            if o and o[0] == 'SELL' and (len(o) >= 3):
                planned[o[1]] = planned.get(o[1], 0) + _int(o[2])
        day = step // self.cfg['turns_per_day']
        extra = []
        for item in PRODUCTS:
            have = projected.get(item, 0) - planned.get(item, 0)
            if have <= 0:
                continue
            surplus = have if day >= 29 else have - self.future_sells(route, item, step + 1)
            if surplus > 0 and view.prices.get(item, 0) > 1:
                extra.append(['SELL', item, surplus])
        extra.sort(key=lambda o: -view.prices.get(o[1], 0) * o[2])
        action['market'] = (action.get('market') or []) + extra

    def _terminal_liquidation(self, action, projected, step):
        if step < LAST_ACT_STEP:
            return
        action['market'] = [['SELL', item, qty] for item, qty in projected.items() if qty > 0 and item in PRODUCTS][:self.cfg['max_orders']]

def make_agent(routes, router=None, opponent_plan=None, **settings):
    chassis = Chassis(routes, router, settings, opponent_plan)

    def agent(observation, configuration=None):
        try:
            return chassis.act(observation, configuration)
        except Exception:
            chassis.diagnostics['entry_fallbacks'] += 1
            try:
                step = _step_of(observation)
                player = _int(_get(observation, 'player', 0))
                tape = chassis.routes.get(chassis.players.get(player, {}).get('route'), next(iter(chassis.routes.values())))
                if 0 <= step < len(tape):
                    return copy.deepcopy(tape[step])
            except Exception:
                pass
            try:
                farms = _get(observation, 'farms', []) or []
                hands = _get(farms[_int(_get(observation, 'player', 0))], 'hands', []) or []
                return {'farmer': ['PASS'], 'hands': [['PASS'] for _ in hands], 'market': []}
            except Exception:
                return copy.deepcopy(PASS_ACTION)
    agent.chassis = chassis
    return agent
